{
  "type": "object",
  "properties": {
    "targeted_spend": {
      "type": "object",
      "description": "{channel_id: {group_id: $/day}}",
      "additionalProperties": {
        "type": "object",
        "additionalProperties": {
          "type": "number"
        }
      }
