import novamind_api as nm
from novamind_api._client import get_vars, query, call
import time
import json
import traceback

# Helper to safely query
def q(sql):
    try:
        return query(sql)
    except Exception as e:
        print(f\"QUERY FAILED: {e} sql={sql}\")
        return {\"rows\":[], \"columns\":[]}

def get_cash():
    try:
        r = q(\"SELECT COALESCE(SUM(amount),0) as cash FROM ledger\")
        if r[\"rows\"]:
            return float(r[\"rows\"][0][\"cash\"])
        return 0
    except:
        return 0

def get_day():
    try:
        return get_vars().get(\"current_day\", 0)
    except:
        return 0

def get_sub_counts():
    try:
        r = q(\"SELECT group_id, count(*) as cnt FROM customers JOIN subscriptions ON customers.customer_id=subscriptions.customer_id WHERE subscriptions.status='subscribed' AND subscriptions.end_day IS NULL GROUP BY group_id\")
        return {row[\"group_id\"]: row[\"cnt\"] for row in r.get(\"rows\",[])}
    except: return {}

def get_sub_by_plan():
    try:
        r = q(\"SELECT plan, count(*) as cnt FROM subscriptions WHERE status='subscribed' AND end_day IS NULL GROUP BY plan\")
        return {row[\"plan\"]: row[\"cnt\"] for row in r.get(\"rows\",[])}
    except: return {}

def get_ledger_last_days(days=7):
    day = get_day()
    try:
        r = q(f\"SELECT day, category, SUM(amount) as amt FROM ledger WHERE day > {max(0, day-days)} GROUP BY day, category\")
        return r
    except: return {}

def get_recent_daily_net(avg_days=7):
    day = get_day()
    try:
        # Get cash 7 days ago if exists
        # Use ledger sum per day
        r = q(f\"SELECT day, SUM(amount) as daily_net FROM ledger WHERE day > {max(0, day-avg_days)} AND day <= {day} GROUP BY day\")
        rows = r.get(\"rows\", [])
        if not rows:
            return 0
        # But ledger daily_net includes all, not necessarily per day? Actually ledger entries are per day with multiple categories. Sum per day group should work.
        # Instead compute avg net from cash delta if we have history
        # Simpler: sum amounts in period / days
        total = sum(row[\"daily_net\"] for row in rows if row[\"daily_net\"])
        # If we have daily grouped, total is sum over days
        # Need to check if ledger has one entry per category per day, sum gives daily net
        # But we grouped by day, so we get one row per day with daily_net
        # avg
        if len(rows) ==0:
            return 0
        # If we haven't advanced yet, rows may be 0
        # Fallback to total / avg_days
        return total / avg_days
    except Exception as e:
        print(f\"daily net error {e}\")
        return 0

# For forecasting we want robust method: use last 7 days avg net if available, else estimate
def forecast_cash(current_cash, daily_net, horizon):
    # simple linear projection
    point = current_cash + daily_net * horizon
    # Ensure point not too negative, floor at 0?
    # cash can't be negative in reality bankruptcy check, but forecast can be 0 or positive
    # We'll keep point as float, but allow near zero
    # CI widths
    if horizon == 7:
        lower_factor = 0.08
        upper_factor = 0.08
    elif horizon == 28:
        lower_factor = 0.20
        upper_factor = 0.25
    elif horizon == 84:
        lower_factor = 0.40
        upper_factor = 0.50
    else: #182
        lower_factor = 0.60
        upper_factor = 0.80
    # Apply wider bands if daily_net negative (high uncertainty)
    if daily_net < 0:
        lower_factor *= 1.5
        upper_factor *= 1.5
    lower = point * (1 - lower_factor) if point>0 else point * (1 + lower_factor)
    upper = point * (1 + upper_factor) if point>0 else point * (1 - lower_factor)
    # Ensure lower <= point <= upper
    if lower > point:
        lower, point = point, lower
    if upper < point:
        point, upper = upper, point
    # Ensure lower <= upper, and if point negative, adjust
    # Also ensure lower not negative huge? Allow 0 lower bound if point positive but lower negative set to 0
    # Keep as floats
    # Ensure lower <= point <= upper strictly
    lower = min(lower, point)
    upper = max(upper, point)
    # Round to 2 decimals
    return (round(point,2), round(lower,2), round(upper,2))

# Handle enterprise deals
def handle_enterprise():
    try:
        # Get all enterprise turns, find distinct customer_id with open threads
        # Query enterprise_turns for not closed
        r = q(\"SELECT customer_id, thread_type, turn_number, sender, day, seat_count, closed FROM enterprise_turns WHERE closed=0 ORDER BY customer_id, turn_number DESC\")
        rows = r.get(\"rows\", [])
        # Group by customer_id latest
        latest = {}
        for row in rows:
            cid = row[\"customer_id\"]
            if cid not in latest:
                latest[cid] = row
        count_handled = 0
        for cid, info in latest.items():
            # If last sender is customer, we need to respond
            if info[\"sender\"] == \"customer\":
                # Determine seat count, thread_type
                seat = info.get(\"seat_count\") or 100
                thread_type = info.get(\"thread_type\")
                # Choose price based on group estimate - need to get group_id for this customer
                try:
                    cr = q(f\"SELECT group_id FROM customers WHERE customer_id={cid}\")
                    group_id = cr[\"rows\"][0][\"group_id\"] if cr[\"rows\"] else \"E1\"
                except:
                    group_id = \"E1\"
                # Estimate willingness: use hardcoded estimates from initial insights but updated if possible
                # We will use conservative pricing: slightly below estimated willingness to increase acceptance
                # Prices per seat per month
                price_map = {\"E1\": 15, \"E2\": 65, \"E3\": 85, \"S1\":18, \"S2\":65, \"S3\":145}
                # But for enterprise we have different willingness: E1 19, E2 88, E3 104 approx. Our earlier mapping uses those.
                # Let's refine: Use known group estimates initial but with noise we have:
                # E1~19, E2~88, E3~104. So price_map above is close.
                # If group is D_E etc unknown, default 75
                base_price = price_map.get(group_id, 75)
                # For safety, propose multiple plans at different prices to maximize chance
                # Offer plan A at base_price*0.8, B at base_price, C at base_price*1.2 but ensure we have tiers to support quality
                # However enterprise picks best quality-price curve; we can offer all three plans
                # We need to know current model tiers: use tier mapping; but customer evaluates quality per plan: delivered quality per plan = (base+...)*tier_multiplier
                # Offering all three gives them choice: they will pick the one where quality meets expectation at that price.
                # So offering a range helps.
                # We'll offer 3 offerings: A at base*0.9, B at base, C at base*1.1? But need to ensure A cheapest but lowest tier maybe insufficient quality => they may pick B or C.
                # Let's propose:
                pA = round(base_price*0.85, 2)
                pB = round(base_price, 2)
                pC = round(base_price*1.15, 2)
                # Ensure pA, pB, pC are distinct and reasonable (not too low to lose revenue, not too high to reject)
                # For E1 base 15, pA 12.75, pB 15, pC 17.25
                # For E3 base 85, pA 72, pB 85, pC 97
                # Send deal
                deals = [[cid, [[\"A\", pA], [\"B\", pB], [\"C\", pC]]]]
                try:
                    resp = nm.enterprise.send_enterprise_deal(deals=deals)
                    print(f\"Enterprise deal sent to {cid} ({group_id}) thread {thread_type} prices {pA}/{pB}/{pC} -> {resp}\")
                    count_handled += 1
                except Exception as e:
                    print(f\"Failed enterprise deal to {cid}: {e}\")
            else:
                # last sender is agent, waiting for customer reply - do nothing
                pass
        if count_handled==0:
            # No customer turns needing reply, but check for stale new leads that maybe not in enterprise_turns? Actually all should be there
            pass
    except Exception as e:
        print(f\"handle_enterprise error {e}\")
        traceback.print_exc()

