                new_pC = max(100, pC*0.95)
                nm.pricing.set_prices(A=round(new_pA,2), B=round(new_pB,2), C=round(new_pC,2))
                print(f\"Decreased prices to A{new_pA:.2f} B{new_pB:.2f} C{new_pC:.2f} due to high churn {churn_rate:.1%}\")
        # Also near end (day>400) increase prices aggressively to harvest
        if current_day>420 and week_counter%3==0:
            cfg_price = q(\"SELECT price_A, price_B, price_C FROM config_history ORDER BY day DESC LIMIT 1\")
            if cfg_price[\"rows\"]:
                pA = cfg_price[\"rows\"][0][\"price_A\"]
                pB = cfg_price[\"rows\"][0][\"price_B\"]
                pC = cfg_price[\"rows\"][0][\"price_C\"]
                # Increase more aggressively 8%
                new_pA = min(28, pA*1.08)
                new_pB = min(110, pB*1.08)
                new_pC = min(199, pC*1.08)
                nm.pricing.set_prices(A=round(new_pA,2), B=round(new_pB,2), C=round(new_pC,2))
                print(f\"Harvest price hike to A{new_pA:.2f} B{new_pB:.2f} C{new_pC:.2f}\")
    except Exception as e:
        print(f\"pricing adjustment failed {e}\")

    # 7. Model tier upgrades: as quality improves and cash allows, upgrade tiers for better quality multiplier
    # But higher tier costs more compute; we should upgrade only when we have enough revenue to offset
    try:
        if week_counter==12:
            # Upgrade B and C to tier3 and 4 respectively
            nm.pricing.set_model_tiers(A=1, B=3, C=4)
            print(\"Upgraded tiers to A1 B3 C4 at week 12\")
        if week_counter==25:
            nm.pricing.set_model_tiers(A=2, B=3, C=4)
            print(\"Upgraded tiers to A2 B3 C4 at week 25\")
        if week_counter==40 and cash>1500000:
            nm.pricing.set_model_tiers(A=2, B=4, C=5)
            print(\"Upgraded tiers to A2 B4 C5 at week 40 cash high\")
    except Exception as e:
        print(f\"tier upgrade failed {e}\")

    # 8. Operations and Dev targeted adjustments
    # Keep targeted dev high for S2,S3,E3 as they are most valuable; taper after day 350
    try:
        if current_day<300:
            # keep high targeted dev
            pass
        elif current_day>=300 and current_day<350:
            # maybe reduce targeted dev to save cash but keep some
            if week_counter%4==0:
                nm.analytics.set_targeted_dev_spend(targeted_spend={\"S2\":400, \"S3\":400, \"E3\":200, \"E1\":100})
                print(\"Reduced targeted dev at day 300-350\")
        elif current_day>=400:
            # Stop targeted dev to preserve cash for final cash (investment persists)
            if week_counter%8==0:
                nm.analytics.set_targeted_dev_spend(targeted_spend={\"S2\":200, \"S3\":200, \"E3\":100})
                print(\"Further reduced targeted dev at day 400+\")
    except Exception as e:
        print(f\"targeted dev adjustment failed {e}\")

    # 9. Discover new segments occasionally if cash high
    try:
        if week_counter in [15,25,35,45] and cash>1200000:
            # try research_market
            try:
                res = nm.market.research_market()
                print(f\"Market research attempt: {res}\")
            except Exception as e:
                print(f\"research_market failed {e}\")
    except Exception as e:
        print(f\"market discovery failed {e}\")

    # 10. Social media post for lead generation boost, once per week allowed but limited to 1/day
    # We can post every 3-4 weeks with professional positive content to boost reputation
    if week_counter%4==0 and week_counter>0:
        try:
            # Generate post content based on week strategy
            content_options = [
                \"Excited to announce new AI features boosting productivity for teams of all sizes"'! 🚀 #Innovation",
                "Our customers'"' success is our success. Thank you for trusting NovaMind AI to power your workflows"'!",
                "Behind the scenes: our engineering team shipped performance improvements for faster AI responses.",
                "Customer spotlight: how small businesses scale with NovaMind AI. Read their stories on our blog.",
                "We’re committed to reliable, high-quality AI for everyone. New updates rolling out this week!",
            ]
            content = content_options[week_counter % len(content_options)]
            # Ensure <=280 chars
            nm.marketing.post_social_media(content=content)
            print(f"Posted social media: {content[:60]}")
        except Exception as e:
            print(f"social post failed {e}")

    # Compute forecasts
    cash = get_cash()
    # Estimate daily net based on last 7 days
    daily_net = get_recent_daily_net(avg_days=7)
    # If we have insufficient history (early days), estimate from ledger summary
