    print(f\"Forecasts: 7d {p7} [{l7},{u7}] 28d {p28} [{l28},{u28}] 84d {p84} [{l84},{u84}] 182d {p182} [{l182},{u182}]\")

    # Generate rationale
    rationale = (
        f\"Week {week_counter} day {current_day} cash "'${cash:,.0f} subs {sum(subs_by_group.values()) if subs_by_group else 0} "
