            print(get_vars())
            print(q(\"SELECT COALESCE(SUM(amount),0) as cash FROM ledger\"))
        except:
            pass
        # Break to avoid infinite loop? But we should exit to allow manual resume
        print(\"Exiting loop due to next_week failure, need manual check\")
